function createPart(name, targetOpacity) {
  const group = new THREE.Group();
  group.name = name;
  group.userData.opacityMaterials = [];
  group.userData.targetOpacity = targetOpacity;
  return group;
}

function addMeshWithEdges(group, geometry, material, edgeThreshold = 22) {
  const mesh = new THREE.Mesh(geometry, material);
  group.add(mesh);
  if (material.transparent) {
    group.userData.opacityMaterials.push(material);
  }
  const edges = new THREE.LineSegments(
    new THREE.EdgesGeometry(geometry, edgeThreshold),
    edgeMaterial
  );
  group.add(edges);
  return mesh;
}

function addLine(group, points, opacity = 1) {
  const geometry = new THREE.BufferGeometry().setFromPoints(points);
  const material = new THREE.LineBasicMaterial({
    color: EDGE_COLOR,
    transparent: true,
    opacity
  });
  const line = new THREE.Line(geometry, material);
  group.add(line);
  return line;
}

function addDashedLine(parent, points) {
  const geometry = new THREE.BufferGeometry().setFromPoints(points);
  const material = new THREE.LineDashedMaterial({
    color: EDGE_COLOR,
    dashSize: 1.6,
    gapSize: 1.0,
    transparent: true,
    opacity: 0
  });
  const line = new THREE.Line(geometry, material);
  line.computeLineDistances();
  line.visible = false;
  parent.add(line);
  dashLines.push(line);
  return line;
}

function extrudePlanarShape(shape, depth) {
  const geometry = new THREE.ExtrudeGeometry(shape, {
    depth,
    bevelEnabled: false,
    curveSegments: 40
  });
  // 将 Shape 从 XY 平面旋转到 XZ 平面，并使厚度沿 Y 轴居中。
  geometry.translate(0, 0, -depth / 2);
  geometry.rotateX(-Math.PI / 2);
  return geometry;
}

function chamferRectShape(w, h, chamfer) {
  const x0 = -w / 2;
  const x1 = w / 2;
  const y0 = -h / 2;
  const y1 = h / 2;
  const c = chamfer;
  const shape = new THREE.Shape();
  shape.moveTo(x0 + c, y0);
  shape.lineTo(x1 - c, y0);
  shape.lineTo(x1, y0 + c);
  shape.lineTo(x1, y1 - c);
  shape.lineTo(x1 - c, y1);
  shape.lineTo(x0 + c, y1);
  shape.lineTo(x0, y1 - c);
  shape.lineTo(x0, y0 + c);
  shape.closePath();
  return shape;
}

// 在最终的 XZ 平面坐标中创建矩形孔；Shape 位于 XY，因此 y = -z。
function rectHoleByXZ(cx, cz, w, h) {
  const p = new THREE.Path();
  const x0 = cx - w / 2;
  const x1 = cx + w / 2;
  const cy = -cz;
  const y0 = cy - h / 2;
  const y1 = cy + h / 2;
  // 与外部轮廓保持相反的绕向，供 holes 使用。
  p.moveTo(x0, y0);
  p.lineTo(x0, y1);
  p.lineTo(x1, y1);
  p.lineTo(x1, y0);
  p.closePath();
  return p;
}

function circleHoleByXZ(cx, cz, radius) {
  const p = new THREE.Path();
  p.absarc(cx, -cz, radius, 0, Math.PI * 2, true);
  return p;
}

function dustLinerShape() {
  const outerRadius = 24;
  const innerRadius = 20;
  const gap = 0.72;
  // 缺口朝向前缘（+Z）。
  const theta0 = -Math.PI / 2 - gap / 2;
  const theta1 = -Math.PI / 2 + gap / 2;

  const shape = new THREE.Shape();
  shape.moveTo(
    innerRadius * Math.cos(theta0),
    innerRadius * Math.sin(theta0)
  );
  shape.lineTo(
