        // (f) WRITE PROTECT NOTCH：右后角。
        outer.holes.push(rectHoleByXZ(27, -27, 3, 3));
        // (g) Shutter opening slot：与上壳/滑盖同一 HEAD_SLOT。
        outer.holes.push(rectHoleByXZ(HEAD_SLOT.cx, HEAD_SLOT.cz, HEAD_SLOT.w, HEAD_SLOT.h));

        const bodyGeo = extrudePlanarShape(outer, 2);
        addMeshWithEdges(part, bodyGeo, makeFillMaterial(FILL_COLOR, 1), 24);

        // (a) 中央大圆形凹陷。
        const recessGeo = new THREE.CylinderGeometry(22, 22, 0.25, 72);
        const recess = addMeshWithEdges(
          part,
          recessGeo,
          makeFillMaterial(FILL_COLOR, 1),
          26
        );
        recess.position.y = 0.76;

        // (c) 四角定位柱。
        const pillarGeo = new THREE.CylinderGeometry(1.5, 1.5, 1.0, 24);
        const pillarPositions = [
          [-24, -24],
          [24, -24],
          [24, 24],
          [-24, 24]
        ];
        pillarPositions.forEach(([px, pz]) => {
          const pillar = addMeshWithEdges(
            part,
            pillarGeo,
            makeFillMaterial(FILL_COLOR, 1),
            24
          );
          pillar.position.set(px, 0.5, pz);
        });

        // (d) LIFTER。
        const lifterGeo = new THREE.BoxGeometry(8, 1, 4);
        const lifter = addMeshWithEdges(
          part,
          lifterGeo,
          makeFillMaterial(FILL_COLOR, 1),
          24
        );
        lifter.position.set(0, 0.5, 18);

        // (e) SHUTTER SPRING 区：前缘中部小矩形凹槽。
        const springGeo = new THREE.BoxGeometry(10, 0.25, 4);
        const spring = addMeshWithEdges(
          part,
          springGeo,
          makeFillMaterial(FILL_COLOR, 1),
          24
        );
        spring.position.set(8, 0.72, 24);

        return part;
      }

      // --- SHUTTER ---
      function createShutter() {
        const part = createPart("SHUTTER", 1.0);

        // 快门板面：长边沿 X，短边沿 Z。矩形通孔短边(6)与快门长边平行。
        const outer = new THREE.Shape();
        outer.moveTo(-20, -29);
        outer.lineTo(2, -29);
        outer.lineTo(2, -13);
        outer.lineTo(-20, -13);
        outer.closePath();
        outer.holes.push(
          rectHoleByXZ(HEAD_SLOT.cx, HEAD_SLOT.cz, HEAD_SLOT.w, HEAD_SLOT.h)
        );

        const geometry = extrudePlanarShape(outer, 1);
        // 快门本体使用不透明实体金属材质。
        addMeshWithEdges(part, geometry, makeOpaqueShutterMaterial(), 22);
        return part;
      }

      // --- WRITE PROTECT TAB ---
      function createWriteProtectTab() {
        const part = createPart("WRITE_PROTECT_TAB", 0.08);
        const geometry = new THREE.BoxGeometry(3, 2, 3);
        addMeshWithEdges(part, geometry, makeFillMaterial(FILL_COLOR, 1), 24);
        return part;
      }

      // === BUILD PARTS ===
      const topShell = createTopShell();
      const dustLinerTop = createDustLiner("DUST_LINER_TOP");
      const hub = createHub();
      const disk = createMagneticDisk();
      const dustLinerBottom = createDustLiner("DUST_LINER_BOTTOM");
      const bottomShell = createBottomShell();
      const shutter = createShutter();
      const writeProtectTab = createWriteProtectTab();

      [topShell, dustLinerTop, hub, disk, dustLinerBottom, bottomShell, shutter, writeProtectTab]
        .forEach((part) => scene.add(part));

      // === ANIMATION: part registration ===
      const parts = [];
      function registerPart(group, from, to, order) {
        parts.push({
          group,
          from: from.clone(),
          to: to.clone(),
          delay: order * STAGGER,
          materials: group.userData.opacityMaterials,
          targetOpacity: group.userData.targetOpacity
        });
      }

      registerPart(topShell, new THREE.Vector3(0, 1.5, 0), new THREE.Vector3(0, 45, 0), 0);
      registerPart(dustLinerTop, new THREE.Vector3(0, 1.0, 0), new THREE.Vector3(0, 30, 0), 1);
      registerPart(hub, new THREE.Vector3(0, 0.7, 0), new THREE.Vector3(0, 18, 0), 2);
      registerPart(disk, new THREE.Vector3(0, 0.5, 0), new THREE.Vector3(0, 15, 0), 3);
      registerPart(dustLinerBottom, new THREE.Vector3(0, 0, 0), new THREE.Vector3(0, 0, 0), 4);
      registerPart(bottomShell, new THREE.Vector3(0, -1.5, 0), new THREE.Vector3(0, -15, 0), 5);
      // SHUTTER 几何本身相对 Group 原点有局部偏移（使窗口对齐 HEAD_SLOT），
      // 因此 exploded Group 位置按“板面中心 = (-30, -15, 30)”反推。
      registerPart(shutter, new THREE.Vector3(0, -1.5, 0), new THREE.Vector3(-21, -15, 9), 6);
      registerPart(writeProtectTab, new THREE.Vector3(26, -1, -26), new THREE.Vector3(38, -15, -38), 7);

      // 初始置于组装态。
      parts.forEach((p) => {
        p.group.position.copy(p.from);
        p.materials.forEach((m) => {
          m.opacity = 1;
        });
      });

      // === ANNOTATIONS / LABELS ===
      const dashLines = [];
      const labelItems = [];

      function createLabel(text, anchor, target) {
        const el = document.createElement("div");
        el.className = "label";
        el.textContent = text;
        el.style.opacity = "0";
        el.style.transition = "opacity 0.4s ease";

        const cssObject = new THREE.CSS2DObject(el);
        cssObject.position.copy(anchor);
        scene.add(cssObject);

        const lineGeo = new THREE.BufferGeometry().setFromPoints([anchor, target]);
        const lineMat = new THREE.LineBasicMaterial({
          color: EDGE_COLOR,
          transparent: true,
          opacity: 0
        });
        const leader = new THREE.Line(lineGeo, lineMat);
        leader.visible = false;
        scene.add(leader);

        labelItems.push({
          dom: el,
          cssObject,
          leader,
          shown: false
        });
      }

      function createAllLabels() {
        createLabel(
          "HD NOTCH",
          new THREE.Vector3(-43, 48, -36),
          new THREE.Vector3(-28, 45, -28)
        );
        createLabel(
          "TOP SHELL",
          new THREE.Vector3(52, 48, -30),
          new THREE.Vector3(40, 45, -24)
        );
        createLabel(
          "DUST LINER",
          new THREE.Vector3(48, 30, 30),
          new THREE.Vector3(24, 30, 20)
        );
        createLabel(
          "DUST LINER",
          new THREE.Vector3(48, 0, -30),
          new THREE.Vector3(24, 0, -20)
        );
        createLabel(
          "MAGNETIC DISK",
          new THREE.Vector3(42, 15, 22),
          new THREE.Vector3(20, 15, 12)
        );
        createLabel(
          "HUB",
          new THREE.Vector3(31, 18, 31),
          new THREE.Vector3(6, 18, 6)
        );
        createLabel(
          "BOTTOM SHELL",
          new THREE.Vector3(52, -15, -32),
          new THREE.Vector3(40, -15, -24)
        );
        createLabel(
          "LIFTER",
          new THREE.Vector3(-38, -15, 40),
          new THREE.Vector3(0, -15, 18)
        );
        createLabel(
          "SHUTTER SPRING",
          new THREE.Vector3(22, -15, 48),
          new THREE.Vector3(8, -15, 24)
        );
        createLabel(
          "WRITE PROTECT NOTCH",
          new THREE.Vector3(50, -15, -42),
          new THREE.Vector3(27, -15, -27)
        );
        createLabel(
          "SHUTTER",
          new THREE.Vector3(-50, -15, 48),
          new THREE.Vector3(-30, -15, 30)
        );
        createLabel(
          "WRITE PROTECT TAB",
          new THREE.Vector3(54, -15, -49),
          new THREE.Vector3(38, -15, -38)
        );
      }

      function createDashedGuides() {
        const corners = [
          [-27, -27],
          [27, -27],
          [27, 27],
          [-27, 27]
        ];
        corners.forEach(([x, z]) => {
          addDashedLine(scene, [
            new THREE.Vector3(x, 45, z),
            new THREE.Vector3(x, -15, z)
          ]);
        });

        // 快门与防写入滑块使用斜向虚线回到下壳对应位置。
        addDashedLine(scene, [
          new THREE.Vector3(-30, -15, 30),
          new THREE.Vector3(-9, -15, 21)
        ]);
        addDashedLine(scene, [
          new THREE.Vector3(38, -15, -38),
          new THREE.Vector3(27, -15, -27)
        ]);
      }

      createAllLabels();
      createDashedGuides();

      // === CONTROLS ===
      let controls;
      function setupControls() {
        controls = new THREE.OrbitControls(camera, renderer.domElement);
        controls.enableRotate = true;
        controls.enableZoom = true;
        controls.enablePan = true;
        controls.enableDamping = true;
        controls.dampingFactor = 0.08;

        // 显式设置 DCC 常见的鼠标操作习惯。
        controls.mouseButtons = {
          LEFT: THREE.MOUSE.ROTATE,
          MIDDLE: THREE.MOUSE.DOLLY,
          RIGHT: THREE.MOUSE.PAN
        };

        controls.minZoom = 0.45;
        controls.maxZoom = 2.8;
        controls.zoomSpeed = 1.0;
        controls.panSpeed = 0.8;
        controls.screenSpacePanning = true;

        renderer.domElement.addEventListener("contextmenu", (event) => {
          event.preventDefault();
        });
      }
      setupControls();

      function clampControlsTarget() {
        controls.target.x = THREE.MathUtils.clamp(controls.target.x, -28, 28);
        controls.target.y = THREE.MathUtils.clamp(controls.target.y, -16, 16);
        controls.target.z = THREE.MathUtils.clamp(controls.target.z, -28, 28);
      }

      // === ANIMATION: state machine ===
      let animState = "assembled";
      let animElapsed = 0;
      let labelTime = 0;

      const hintEl = document.getElementById("hint");
      const leftTitleEl = document.getElementById("side-left");
      const rightTitleEl = document.getElementById("side-right");
      leftTitleEl.textContent = "FIG_001";
      rightTitleEl.textContent = '[ 3.5" FLOPPY DISK ]';

      function easeInOutCubic(t) {
        return t < 0.5
          ? 4 * t * t * t
          : 1 - Math.pow(-2 * t + 2, 3) / 2;
      }

      function applyPart(part, progress) {
        part.group.position.lerpVectors(part.from, part.to, progress);
        const opacity = THREE.MathUtils.lerp(1, part.targetOpacity, progress);
        part.materials.forEach((material) => {
          material.opacity = opacity;
        });
      }

      function updateHintVisibility() {
        hintEl.classList.toggle("hidden", animState !== "assembled");
      }

      function showLabels() {
        labelTime = 0;
      }

      function hideLabels() {
        labelTime = 0;
        labelItems.forEach((item) => {
          item.shown = false;
          item.dom.style.opacity = "0";
          item.leader.visible = false;
          item.leader.material.opacity = 0;
        });
        dashLines.forEach((line) => {
          line.material.opacity = 0;
        });
        // 等 CSS 淡出大致结束后再彻底隐藏虚线。
        setTimeout(() => {
          if (animState !== "exploded") {
            dashLines.forEach((line) => {
              line.visible = false;
            });
          }
        }, 320);
      }

      // === ANIMATION: explode trigger ===
      function triggerExplode() {
        if (animState !== "assembled") return;
        animState = "exploding";
        animElapsed = 0;
        updateHintVisibility();
      }

      // === ANIMATION: collapse trigger ===
      function triggerCollapse() {
        if (animState !== "exploded") return;
        hideLabels();
        animState = "collapsing";
        animElapsed = -0.3; // 先给标注留出约 0.3s 的淡出时间。
        updateHintVisibility();
      }

      function updateLabelTimeline(dt) {
        labelTime += dt;

        const dashStart = 0.2;
        const dashDuration = 0.6;
        const dashProgress = easeInOutCubic(
          THREE.MathUtils.clamp((labelTime - dashStart) / dashDuration, 0, 1)
        );
        dashLines.forEach((line) => {
          line.visible = true;
          line.material.opacity = dashProgress;
        });

        const labelStart = 0.4;
        const labelInterval = 0.06;
        labelItems.forEach((item, index) => {
          if (!item.shown && labelTime >= labelStart + index * labelInterval) {
            item.shown = true;
            item.dom.style.opacity = "1";
            item.leader.visible = true;
            item.leader.material.opacity = 1;
          }
        });
      }

      function updateAnimation(dt) {
        if (animState === "exploding") {
          animElapsed += dt;
          parts.forEach((part) => {
            const local = THREE.MathUtils.clamp(
              (animElapsed - part.delay) / ANIM_DURATION,
              0,
              1
            );
            applyPart(part, easeInOutCubic(local));
          });

          const lastDelay = (parts.length - 1) * STAGGER;
          if (animElapsed >= ANIM_DURATION + lastDelay) {
            animState = "exploded";
            showLabels();
            updateHintVisibility();
          }
        } else if (animState === "collapsing") {
          animElapsed += dt;
          if (animElapsed < 0) return;

          const lastDelay = (parts.length - 1) * STAGGER;
          parts.forEach((part) => {
            const reverseDelay = lastDelay - part.delay;
            const local = THREE.MathUtils.clamp(
              (animElapsed - reverseDelay) / ANIM_DURATION,
              0,
              1
            );
            // 收起时 e=0 保持爆炸态，e=1 回到组装态。
            applyPart(part, 1 - easeInOutCubic(local));
          });

          if (animElapsed >= ANIM_DURATION + lastDelay) {
            animState = "assembled";
            updateHintVisibility();
          }
        } else if (animState === "exploded") {
          updateLabelTimeline(dt);
        }
      }

      window.addEventListener("keydown", (event) => {
        if (event.code === "Space") {
          event.preventDefault();
          if (animState === "assembled") {
            triggerExplode();
          } else if (animState === "exploded") {
            triggerCollapse();
          }
          // 动画进行中按空格被忽略，避免状态混乱。
        }
      });

      window.addEventListener("resize", () => {
        updateCameraFrustum();
        renderer.setSize(window.innerWidth, window.innerHeight);
        cssRenderer.setSize(window.innerWidth, window.innerHeight);
      });

      // === RENDER LOOP ===
      const clock = new THREE.Clock();
      function render() {
        requestAnimationFrame(render);
        const dt = Math.min(clock.getDelta(), 0.1);
        updateAnimation(dt);
        controls.update();
        clampControlsTarget();
        renderer.render(scene, camera);
        cssRenderer.render(scene, camera);
      }

      updateHintVisibility();
      render();
    })();
  </script>

  <!--
    快门与开孔自检：
    1. SHUTTER 本体使用 MeshBasicMaterial #4A5568，transparent 为 false，是不透明金属板，
       未使用 0.08 的爆炸态半透明填充。
    2. SHUTTER 通过 Shape + holes + ExtrudeGeometry 做出真正的矩形通孔；HEAD_SLOT 在板面
       左偏（cx = -9），开孔短边 6 与快门长边(X)平行、长边 14 与快门短边(Z)平行。
    3. TOP SHELL (d) 与 BOTTOM SHELL (g) 均复用 HEAD_SLOT 的 cx/cz/w/h，组装态下三处开孔
       完全对齐，形成连续磁头通道。
  -->
</body>
</html>
